        need=((r1-r0-1)*(c1-c0-1))//2
        candidates=[col for col,n in counts.items() if n==need]
        if len(candidates)==1:
            fill=candidates[0]
            for r in range(r0+1,r1):
                for c in range(c0+1,c1):
                    if (r-r0-1+c-c0-1)%2==0:
                        out[r][c]=fill
    return out
'''
